use std::fs

fn find(keys: Vec<int>, k: int) -> int {
    let mut idx: int = -1
    for i in 0..keys.len() {
        if keys[i] == k {
            idx = i
        }
    }
    idx
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap: int = 1
    let mut keys: Vec<int> = []
    let mut vals: Vec<int> = []
    let mut first = true
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let i = find(keys, k)
            if i >= 0 {
                keys.remove(i)
                vals.remove(i)
            }
            keys.push(k)
            vals.push(v)
            if keys.len() > cap {
                let ek = keys[0]
                keys.remove(0)
                vals.remove(0)
                println("evict ${ek}")
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let i = find(keys, k)
            if i < 0 {
                println("-1")
            } else {
                let v = vals[i]
                keys.remove(i)
                vals.remove(i)
                keys.push(k)
                vals.push(v)
                println("${v}")
            }
        } else if cmd == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let mut out: Vec<string> = []
                let mut j = keys.len()
                while j > 0 {
                    j -= 1
                    out.push("${keys[j]}")
                }
                println(out.join(" "))
            }
        }
    }
}

